export type GitSource = GithubSource | GitlabSource | BitbucketSource | AzureDevopsSource | GitProxySource | S3TestSource | ArtifactsSource;
export type GitSourceType = 'github' | 'gitlab' | 'bitbucket' | 'azure-devops' | 'git-proxy' | 's3-test' | 'artifacts';
type GitSourceBase = {
    type: GitSourceType;
    owner: string;
    repo: string;
    deployBranch: string;
    contentDirectory: string;
    isPrivate: boolean;
};
export type GitProxyAuthMethodType = 'iam-role-assumption';
export type GitProxySigningMethod = GitProxySigV4SigningMethod;
export type GitProxySigV4SigningMethod = {
    type: 'sigv4';
    region: string;
    service: string;
};
export type GitProxyAuthMethod = GitProxyIamRoleAssumptionAuth;
export type GitProxyIamRoleAssumptionAuth = {
    type: 'iam-role-assumption';
    roleArnChain: Record<number, string>;
};
export type GithubSource = {
    type: 'github';
} & GitSourceBase;
export type GitlabSource = {
    type: 'gitlab';
    projectId: number;
    hostUrl?: string;
} & GitSourceBase;
export type BitbucketSource = {
    type: 'bitbucket';
} & GitSourceBase;
export type AzureDevopsSource = {
    type: 'azure-devops';
    projectName: string;
    repositoryId?: string;
} & GitSourceBase;
export type GitProxySource = {
    type: 'git-proxy';
    package: string;
    authMethod: GitProxyAuthMethod;
    signingMethod?: GitProxySigningMethod;
    hostUrl: string;
    supportsGetContent?: boolean;
} & GitSourceBase;
export type S3TestSource = {
    type: 's3-test';
} & GitSourceBase;
export type ArtifactsSource = {
    type: 'artifacts';
} & GitSourceBase;
export {};
